}



/*-----------------------------------------------------------------------------------*/

/*  Typography

/*-----------------------------------------------------------------------------------*/

.rs-menu li {

  font-size: 14px;

}



.rs-menu .sub-menu li a {

  padding: 10px 14px;

}



/* Sub-menus - font size and text alignment*/

.rs-menu ul ul a {

  font-size: 15px;

  text-align: left;

}





/*-----------------------------------------------------------------------------------*/

