html,
body {
  font-size: 15px;
  color: #505050;
  font-family: 'Rubik', sans-serif;
  vertical-align: baseline;
  line-height: 26px;
  font-weight: 400;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
}

p {
  margin: 0 0 26px;
  line-height: 1.8;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: 'Nunito', sans-serif;
  color: #111111;
  margin: 0 0 26px;
  line-height: 1.2;
}

h1 {
  font-size: 70px;
  font-weight: 700;
}

h2 {
  font-size: 36px;
  font-weight: 700;
}

h3 {
  font-size: 26px;
  font-weight: 700;
}

h4 {
  font-size: 24px;
  font-weight: 700;
}

h5 {
  font-size: 18px;
  font-weight: 700;
}

h6 {
  font-size: 16px;
  font-weight: 700;
}

.home-style2 h1,
.home-style2 h2,
.home-style2 h3,
.home-style2 h4,
.home-style2 h5,
.home-style2 h6 {
  color: #112958;
}

.uppercase {
  text-transform: uppercase !important;
}

.capitalize {
  text-transform: capitalize !important;
}

.bold-text {
  font-size: 20px;
  font-weight: bold;
  font-family: 'Nunito', sans-serif;
}

.extra-bold {
  font-weight: 800 !important;
}

a {
  color: #21a7d0;
  transition: all 0.3s ease;
  text-decoration: none !important;
  outline: none !important;
}

a:active,
a:hover {
  text-decoration: none;
  outline: 0 none;
  color: #21a7d0;
}

ul {
  list-style: outside none none;
  margin: 0;
  padding: 0;
}

.clear {
  clear: both;
}

::-moz-selection {
  background: #21a7d0;
  text-shadow: none;
  color: #ffffff;
}

::selection {
  background: #21a7d0;
  text-shadow: none;
  color: #ffffff;
}

.border-none:last-child {
  border-right: none !important;
}

.width-unset {
  width: unset !important;
}

.white-bg {
  background-color: #ffffff;
}

.primary-bg {
  background: #21a7d0;
}

.secondary-bg {
  background: #273c66;
}

.title-bg {
  background: #111111;
}

.gray-bg {
  background: #f3f8f9;
}

.gray-bg3 {
  background: #e7f9fb;
}

.gray-bg2 {
  background: #e7f6f9;
}

.gray-bg4 {
  background: #F9F7F8;
}

.event-bg {
  background: #f9f8f8;
}

.event2-bg {
  background: #F4F6F5;
}

.dark-red {
  background: #1D0E15;
}

.bg-light-gray {
  background: #f9f9f9;
}

.transparent-bg {
  background: transparent;
}

.home5color {
  color: #54647b !important;
}

.bg-fixed {
  background-attachment: fixed;
  background-repeat: no-repeat;
}

.bg1 {
  background: url('../assets/images/bg/bg1.png');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
}

.bg2 {
  background: url('../assets/images/bg/bg2.jpg');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
