}

.pagination-area .pagination-part li:before {
  content: '';
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #d6fbff;
}

.pagination-area .pagination-part li:last-child:before {
